Let $B$ be a seminormed space, let $a:{\mathbb N}\to B$, let $r_0\ge2$, and let $D>0$. Assume that, for every $J\ge1$ and every $0<N_0<\cdots<N_J$,
\begin{equation}
\sum_{j\in[J)}\|a(N_{j+1})-a(N_j)\|^2\le D J^{1-2/r_0}.
\end{equation}
If $r>r_0$, then
\begin{equation}
\|a\|_{V_r(N\in{\mathbb N},\ N\ge1;B)}
\le 2^{1-1/r_0}\left(\tfrac{r}{r-r_0}\right)^{1/r}D^{1/2}.
\end{equation}
If $r_0=2$, then
\begin{equation}
\|a\|_{V_2(N\in{\mathbb N},\ N\ge1;B)}\le D^{1/2}.
\end{equation}

For $n\in{\mathbb N}$ and $r>0$ and $x\in {\mathbb R}^n$ denote
\begin{equation} B_n(x,r) := \{ \xi\in\mathbb{R}^n\,:\, |\xi-x|\le r \} \end{equation}
\begin{equation} B_n(r) := B_n(0,r) \end{equation}

The standard Gaussian on ${\mathbb R}$ is defined by
\begin{equation}
\mathfrak{g}(x)=e^{-\pi x^2}
\end{equation}
for $x\in{\mathbb R}$. This is chosen so that $\int_{{\mathbb R}}\mathfrak{g}=1$.

Define
\begin{equation}
\left<x\right>:=(1+|x|)^{-1}\, .
\end{equation}
We agree on the following parsing, which interprets the power first:
\begin{equation}
\left<x\right>^N_{(s)}:=(\left< .\right>^N)_{(s)}(x)=s^{-1}(1+|s^{-1}x|)^{-N}\, .
\end{equation}

Let $d\in {\mathbb N}$ and $f:{\mathbb R}^d\to \mathbb{K}$ be continuous.
Then for $r\in (0,\infty)$, the function $g:{\mathbb R}^d\to [0,\infty]$  defined by
\begin{equation}
g(x)=\sup_{|x-y|\le r}|f(y)|
\end{equation}
is finite and upper semi continuous and measurable.

Let $d\in {\mathbb N}$.  Define
\begin{equation}
\|f\|_{W_0,d,r}:=    \int_{{\mathbb R}^d} \sup_{|x-y|\le r} |f(y)|\,dx.
\end{equation}
As $d$ can be inferred from the type of $f$, we
will omit it from the notation.
We also set
\begin{equation}
\|f\|_{W_0}:=\|f\|_{W_0,1}\, .
\end{equation}
Write $W_0({\mathbb R}^d)$ or $W_0(d)$ for the set of continuous functions $f:{\mathbb R}^d\to\mathbb{K}$ so that
\begin{equation}  \|f\|_{W_0}< \infty\, . \end{equation}
We also say that $f$ is in $W_0$ as again the type of $f$
determines $d$.

Let $d\in {\mathbb N}$.
Let $0<r,s<\infty$ and set
\begin{equation}
C_{\ref{W_0 radius independence},d,r,s}:=\max(1,(3s/r)^d)\, .
\end{equation}

Then for all continuous
$f:{\mathbb R}^d\to \mathbb{K}$ we have
\begin{equation}
\|f\|_{W_0,s}\le C_{\ref{W_0 radius independence},d,r,s}\|f\|_{W_0,r}\, .
\end{equation}
In particular, for every $0<r<\infty$, a  continuous
$f:{\mathbb R}^d\to \mathbb{K}$ is in $W_0$ if and only if $\|f\|_{W_0,r}<\infty$.

Let $d\in {\mathbb N}$ be given and set
\begin{equation}
C_{\ref{P:lp-embedding},d}:=\pi^{d/2}\Gamma(d/2+1)^{-1}\, .
\end{equation}
If $f\in W_0(d)$ and $1\le p\le \infty$, then
\begin{equation}
\|f\|_p\le C_{\ref{P:lp-embedding},d}^{\tfrac 1p -1}\|f\|_{W_0}    \, .
\end{equation}

For every injective linear map $\pi:{\mathbb R}^{m}\times {\mathbb R}^{l}\to {\mathbb R}^n$ with $m,l\in{\mathbb N}$, $1\le m+l\le n$
there are $0<C_{\ref{W_0 fiber integrals},\pi,1},C_{\ref{W_0 fiber integrals},\pi,2}<\infty$ such that the following holds. For every $f\in W_0(n)$ and $u\in{\mathbb R}^m$, the function $h_u$ defined by
\begin{equation}
h_u(v)=f(\pi(u,v))
\end{equation}
is in $W_0(l)$ with
\begin{equation}
\|h_u\|_{W_0}\le C_{\ref{W_0 fiber integrals},\pi,1} \|f\|_{W_0}\, .
\end{equation}
The function $g:{\mathbb R}^m\to {\mathbb C}$ defined by
\begin{equation} g(u) := \int_{{\mathbb R}^l} f(\pi(u,v)) \,dv= \int_{{\mathbb R}^l} h_u(v) \,dv \end{equation}
is in $W_0(m)$ with
\begin{equation}
\|g\|_{W_0}\le C_{\ref{W_0 fiber integrals},\pi,2}  \|f\|_{W_0}\, .
\end{equation}

Let $J\in {\mathbb N}$ with $J\ge 1$. For $j\in [J)$, let $I_j\subset {\mathbb N}$ and assume the $I_j$ are pairwise disjoint.
Set $I:=\bigcup_{j\in [J)}I_j$. Let $f_j:{\mathbb R}^{|I_j|}\to \mathbb{K}$ in $W_0(|I_j|)$ and define
\begin{equation}
f(x_I)=\prod_{j\in [J)}f_j(x_{I_j})\, .
\end{equation}
Then $f\in W_0(|I|)$ and
\begin{equation}
\|f\|_{W_0}\le \prod_{j\in [J)}\|f_j\|_{W_0}\, .
\end{equation}

Let  $m,l\in{\mathbb N}$, $m+l\le n$ and assume $l\neq 0$.
Let $J\in {\mathbb N}$ with $J\ge 1$. For $j\in [J)$, let $l_j\in {\mathbb N}$ and let  $\Pi_j:{\mathbb R}^m\times {\mathbb R}^l \to {\mathbb R}^{l_j}$
be a linear map such that
\begin{equation}
\bigcap_{j\in [J)} {\rm ker}\Pi_j=\{0\}\, .
\end{equation}
Then there is $C>0$ such that the following holds.
For $j\in [J)$, let $f_j\in W_0({\mathbb R}^{l_j})$. Then for each
$u\in {\mathbb R}^m$, the function
\begin{equation}
v\to \prod_{j\in [J)}f_j(\Pi_{j}(u,v))
\end{equation}
is in $W_0({\mathbb R}^l)$ and with $f$ defined by
\begin{equation}
f(u):=\int_{{\mathbb R}^l}\prod_{j\in [J)}f_j(\Pi_{j}(u,v))\, dv \, ,
\end{equation}
we have $f\in W_0({\mathbb R}^{m})$ and
\begin{equation}
\|f\|_{W_0}\le C\prod_{j\in[J)}\|f_j\|_{W_0}\, .
\end{equation}

Let $\mathfrak{F}$ be the set of tuples
$\mathbf{F}=(F_i)_{i\in [n)}$ of real-valued functions in $\mathcal{S}({\mathbb R}^n)$

satisfying for $i\in [n)$ the normalization
\begin{equation} \|F_{i}\|_{2^{i+\min(n-i,2)}}=1. \end{equation}
In other words,
\begin{equation}
\|F_{i}\|_{2^{i+2}}=1\;\text{if}\;i\le n-2\;\text{and}\;\|F_{n-1}\|_{2^{n}}=1  \, .
\end{equation}

Define for $k\in{\mathbb N}$ with $1 \le k\le  n$
and  $L\in W_0({\mathbb R}^k)$ and $F\in W_0({\mathbb R}^n)$
\begin{equation} \Theta_{{\rm cube}}(k,L)(F) = \int_{({\mathbb R}^2)^k} \int_{{\mathbb R}^{n-k}} L(y^1-y^0) \Big(\prod_{h\in [2)^k} F(y^h, x_{[k,n)})\Big)^{2^{\min(n-k,1)}}\;dx_{[k,n)}\,dy.\end{equation}

Let $k\in{\mathbb N}$ satisfy $1 \le k\le n$.  Let $L\in W_0({\mathbb R}^k)$. Then, for all $F\in W_0({\mathbb R}^n)$ with $\|F\|_{2^{k+\min(n-k,1)}}=1$,
\begin{equation}
|\Theta_{\rm cube}(k,L)(F)| \le\|L\|_1 .
\end{equation}

Let $k\in{\mathbb N}$ satisfy $1\le k\le n$ and $K\in W_0({\mathbb R}^{k+1})$ and $\mathbf{F}\in \mathfrak{F}$. Then
\begin{equation}
|\Theta_k(K)(\mathbf{F})| \le \|K\|_1.
\end{equation}

Let $K\in W_0({\mathbb R}^{n+1})$. If for all $z\in {\mathbb R}^{n+1}$ we have
\begin{equation}
\int_{\mathbb R} K(z+qe_n)\, dq=0\, ,
\end{equation}
then for all $\mathbf{F}\in \mathfrak{F}$,
\begin{equation}
\Theta_n(K)(\mathbf{F})= 0\, .
\end{equation}

Let $J\ge 1$ and $1\le k<n$ be integers. For
$(\rho_j)_{j\in [J)}\subset W_0({\mathbb R}^{k+1})$, and
$(\phi_j)_{j\in [J)}\subset W_0({\mathbb R})$, define, for $u\in {\mathbb R}^{k+1}$,
\begin{equation}
K(u):=\sum_{j\in[J)}\int_{\mathbb R} \rho_j(u_{[k)},u_k-q)\phi_j(q)\,dq\,.
\end{equation}

Then $K\in W_0({\mathbb R}^{k+1})$ by Proposition \ref{W_0 Brascamp Lieb}.
For $u\in {\mathbb R}^{k+2}$, define
\begin{equation}
\tilde{K}(u):=\sum_{j\in[J)}\int_{\mathbb R}
|\rho_j|(u_{[k)},u_{k+1}-q)\phi_j(u_k+q)\phi_j(q)\,dq\, .
\end{equation}
Then $\tilde{K}\in W_0({\mathbb R}^{k+2})$.
Moreover, for all $\mathbf{F}\in\mathfrak{F}$,
\begin{equation}
|\Theta_k(K)(\mathbf{F})|^2
\le \Theta_{k+1}(\tilde{K})(\mathbf{F})\sum_{j\in[J)}\|\rho_j\|_1\, .
\end{equation}

