Let $J\ge 1$ be an integer. For $(\rho_j)_{j\in[J)}\subset W_0({\mathbb R}^n)$ and
$(\phi_j)_{j\in [J)}\subset W_0({\mathbb R})$ define for $u\in {\mathbb R}^n$,
\begin{equation}
K(u):=\sum_{j\in [J)}\int_{{\mathbb R}^2} \rho_j(u_{[n-1)}, u_{n-1}-r-s) \phi_j(r) \phi_j(s) \, ds dr\, .
\end{equation}
Then $K\in W_0({\mathbb R}^n)$.
For $u\in{\mathbb R}^{n+1}$ let
\begin{equation}
\tilde{K}(u):=\sum_{j\in [J)}\int_{\mathbb R} |\rho_j|(u_{[n-1)}, u_{n}-q) \phi_j(u_{n-1}+q) \phi_j(q) \, dq\, .
\end{equation}
Then $\tilde{K}\in W_0({\mathbb R}^{n+1})$ and for all $\mathbf{F}\in\mathfrak{F}$,
\begin{equation}
|\Theta_{n-1}(K)(\mathbf{F})| \le \sup_{\mathbf{\tilde{F}}\in\mathfrak{F}} |\Theta_{n}(\tilde{K})(\mathbf{\tilde{F}})|.
\end{equation}

Let $1\le k\le n-1$. Let $\rho\in W_0({\mathbb R}^{k+1})$ be non-negative and
$\phi\in W_0({\mathbb R})$. Set for $u\in{\mathbb R}^{k+2}$ and $i\in [k+1)$
\begin{equation}
K(u):=\int_{\mathbb R} \rho(u_{[k+1)\setminus i}, u_{k+1}-q) \phi(u_{i}+q) \phi(q) \, dq\, .
\end{equation}
Then $K\in W_0({\mathbb R}^{k+2})$ and for all $\mathbf{F}\in\mathfrak{F}$
\begin{equation}
\Theta_{k+1}(K)(\mathbf{F})\ge 0\, .
\end{equation}

In the situation of Proposition \ref{Positivity K},
in particular, if $\rho\le \tilde{\rho}$ and
\begin{equation} K_\rho(u):=\int_{\mathbb R} \rho(u_{[k)}, u_{k+1}-q) \phi(u_{k}+q) \phi(q) \, dq\end{equation}
then
\begin{equation} \Theta_{k+1}(K_\rho)(\mathbf{F}) \le \Theta_{k+1}(K_{\tilde{\rho}})(\mathbf{F}) \end{equation}

Let $k\in{\mathbb N}$ satisfy $1\le k\le n$. Let $M\in W_0(({\mathbb R}^2)^k)$.
Define for $z\in {\mathbb R}^{k+1}$,
\begin{equation}
K_k(M)(z)=\int_{{\mathbb R}^{k-1}}  M((z_{l}+p_{l},p_{l})_{l\in [k-1)}, z_{k-1}+z_{k}-\Sigma(p),z_{k}-\Sigma(p))\,dp.
\end{equation}
The integrand is in $W_0({\mathbb R}^{k-1})$ for every $z\in{\mathbb R}^{k+1}$.
The argument of $M$ is identified with an element of $({\mathbb R}^2)^{k}$.
Then $K_k(M)\in W_0({\mathbb R}^{k+1})$ and
\begin{equation} \|K_k(M)\|_1 \le \|M\|_1. \end{equation}

Let $1\le k\le n$ and $i\in [k)$. Let $\tilde{M}\in W_0(({\mathbb R}^2)^{k-1})$ be nonnegative
and let $\phi\in W_0({\mathbb R})$ be real valued. Define for $y\in ({\mathbb R}^2)^k$,
\begin{equation}
M(y)=\tilde{M}(y_{[k)\setminus i}) \phi^{\otimes 2}(y_{i}).
\end{equation}
Then $M\in W_0(({\mathbb R}^2)^k)$ and for all $\mathbf{F}\in {\mathfrak{F}}$,
\begin{equation}
\Lambda_k(M)(\mathbf{F})\ge 0.
\end{equation}

Let $k,J\in{\mathbb N}$ with $1\le k<n-1$ and $J\ge1$. For $j\in[J)$, let $\rho_j\in W_0(({\mathbb R}^2)^k)$ and let $\varphi_j\in W_0({\mathbb R})$ be real valued. Let $i\in[k)$. Let $M\in W_0(({\mathbb R}^2)^k)$ and $\widetilde M\in W_0(({\mathbb R}^2)^{k+1})$ be defined by
\begin{equation}
M=\sum_{j\in[J)}\rho_j*_{e_i^0+e_i^1}\varphi_j,
\end{equation}
and, for $y\in({\mathbb R}^2)^{k+1}$,
\begin{equation}
\widetilde M(y)=\sum_{j\in[J)}|\rho_j(y_{[k)})|\varphi_j^{\otimes2}(y_k).
\end{equation}
Then for all $\mathbf{F}\in\mathfrak F$,
\begin{equation}
|\Lambda_k(M)(\mathbf{F})|
\le
|\Lambda_{k+1}(\widetilde M)(\mathbf{F})|^{1/2}
\Big(\sum_{j\in[J)}\|\rho_j\|_1\Big)^{1/2}.
\end{equation}

Let $J\in{\mathbb N}$ with $J\ge1$ and, for $j\in [J)$, let
$\rho_j\in W_0(({\mathbb R}^2)^{n-1})$  and $\varphi_j\in W_0({\mathbb R})$ be real valued.
Let $i \in [n-1)$.
Define
\begin{equation}
M=\sum_{j\in [J)} \rho_j *_{e_i^0+e_i^1} (\varphi_j * \varphi_j),
\end{equation}
and for $y\in ({\mathbb R}^2)^n$,
\begin{equation}
\tilde{M}(y)=\sum_{j\in [J)} |\rho_j(y_{[n-1)})| \varphi_j^{\otimes 2}(y_{n-1}).
\end{equation}
Then $M\in W_0(({\mathbb R}^2)^{n-1})$ and $\tilde{M}\in W_0(({\mathbb R}^2)^n)$ and for all $\mathbf{F}\in\mathfrak{F}$
\begin{equation}
|\Lambda_{n-1}(M)(\mathbf{F})| \le \sup_{\mathbf{\tilde{F}}\in\mathfrak{F}}|\Lambda_{n}(\tilde{M})(\mathbf{\tilde{F}})|.
\end{equation}

A sequence $a:{\mathbb Z}\to{\mathbb R}$ with $a(j)>0$ for every $j\in{\mathbb Z}$ is called multiplicatively spaced if, for each $j\in{\mathbb Z}$
\begin{equation}
2a(j)\le a(j+1)\, .
\end{equation}
Let ${\rm A}$ be the set of such sequences.

Given $a,b\in {\rm A}$, define
\begin{equation}
\operatorname{dist}(a,b)=\min\{k\in\mathbb{Z}_{\ge 0}\,:\,\forall j, a(j-k)\le b(j)\le a(j+k)\}
\end{equation}
with the understanding that the value is $\infty$ if there is no such $k$.

The function
\begin{equation}
f(x)=\sqrt{1-\mathfrak{g}(x)}
\end{equation}
is well-defined
using the nonnegative square root and is continuous on ${\mathbb R}$.
For $|x|\le \frac 12$, we have
\begin{equation}
f(x)\ge \tfrac 12 |x|
\end{equation}
and for $|x|\ge \frac 12$ we have
\begin{equation}
1-\mathfrak{g}(x)\le f(x)\le 1.
\end{equation}

For every $x\in{\mathbb R}$, $m,N\in{\mathbb N}$,
\begin{equation} |\mathfrak{g}^{(m)}(x)|\le C_{\ref{Gaussian bump decay},m,N} \langle x\rangle^N, \end{equation}
where
\begin{equation}
C_{\ref{Gaussian bump decay},m,N}
=\bigl(38(m+1)\bigr)^{m/2}\bigl(4(N+1)\bigr)^{N/2}.
\end{equation}

(i) $\mathfrak{g}\in \mathcal{S}({\mathbb R})\subset W_0({\mathbb R})$

(ii) $\widehat{\mathfrak{g}}=\mathfrak{g}$.

(iii) We have for $\lambda,\mu>0$
\begin{equation}  \mathfrak{g}_{(\lambda)}*\mathfrak{g}_{(\mu)}=\mathfrak{g}_{(\sqrt{\lambda^2+\mu^2})}\, .
\end{equation}

(iv) We have for $\lambda>0$
\begin{equation}
\widehat{\mathfrak{g}_{(\lambda)}}(\xi)=\mathfrak{g}(\lambda \xi)
\end{equation}

Let
\begin{equation}
p(x)=2(1+(2\pi x)^2)^{-1}.
\end{equation}
Then
\begin{equation}
\widehat{p}(\xi)=e^{- |\xi|}.
\end{equation}

With $p$ as in Proposition \ref{poisson to abel}, define $B:{\mathbb R}\to {\mathbb R}$ by
\begin{equation}
B(\xi):=1-\sqrt{1-\mathfrak{g}(\xi)}-\widehat{p}(\sqrt{\pi}\xi)\, .
\end{equation}
Then $B$ is smooth on ${\mathbb R}\setminus \{0\}$ and continuous on ${\mathbb R}$. The function $B'$
has a continuous extension to ${\mathbb R}$ which is integrable and the
function $B''$, extended to be $0$ at $0$, is Borel measurable and integrable on ${\mathbb R}$.
Moreover,
\begin{equation}
\|B\|_1\le 8,\qquad
\|B'\|_1\le 20,\qquad
\|B''\|_1\le 56.
\end{equation}

For $x\in{\mathbb R}$ let
\begin{equation} \rho(x) = \mathcal{F}^{-1}(\xi \mapsto 1- \sqrt{1-\mathfrak{g}(\xi)})(x). \end{equation}
This is a well-defined function in $W_0({\mathbb R})$ satisfying for all $x\in{\mathbb R}$,
\begin{equation}
0\le \rho(x) \le C_{\ref{square root of Gaussian decay}} \langle x\rangle^2,
\end{equation}
where $C_{\ref{square root of Gaussian decay}}=19$.

Let $N\geq 2$ be an integer. Let $\zeta:{\mathbb R}\to{\mathbb C}$ be an $N$ times continuously differentiable function with compact support.
Then the function $\phi=\mathcal F^{-1} \zeta$ belongs to $W_0({\mathbb R})$ and we have for all $x\in {\mathbb R}$ the estimate
\begin{equation}
|\phi(x)|\leq C_{\ref{lem:smoothdecay2}, N} \max(\|\widehat{\phi}\|_\infty, (2\pi )^{-N}\|\widehat{\phi}^{(N)}\|_\infty)|\operatorname{supp} (\widehat{\phi})|   \langle x\rangle^{N}
\end{equation}
with $C_{\ref{lem:smoothdecay2}, N}=2^{N} $.

Define, for \(l\in{\mathbb N}\) with \(l\ge1\),
\begin{equation}
\Phi_l
=
\widehat{1_{[-3/4,3/4]}}
\prod_{i\in [l)}
2^{i+2}
\widehat{1_{[-2^{-i-3},2^{-i-3}]}} .
\end{equation}
For $x\in{\mathbb R}$, define
\begin{equation}\Phi(x)=\lim_{l\to\infty}\Phi_l(x).\end{equation}
(The limit exists for every $x\in{\mathbb R}$.)

