Let $c>0$, $N\in \mathbb N$ and assume that $\phi$ is a $W_0({\mathbb R})$ function such that
$\widehat{\phi}$ is supported in $[-1,1]$ and equal to $1$ on $[-1/2,1/2]$ and $\widehat{\phi}$ is $N$ times continuously differentiable and $\max_{0\leq m \leq N} \|\widehat{\phi}^{(m)}\|_{\infty} \leq c$.
Assume that $0<\mu \leq \lambda \leq 1/2$, $t\geq \sqrt{3}/2$ and $\nu \in [-1,0)$. For $\xi \in {\mathbb R}$, we define
\begin{equation}
R(\xi)=(\mathfrak{g}(\mu\xi))^{-1}\left(\widehat{\phi}(\lambda\xi)-\widehat{\phi}(\xi)\right)\left((1-\mathfrak{g}(t\xi))^{\nu} -1\right).
\end{equation}
Then $R$ is $N$ times continuously differentiable and
\begin{equation}
(2\pi)^{-N} \max(\|R^{(N)}\|_1,\|R^{(N)}\|_\infty) \leq cC_{\ref{L:second-gaussian-estimate},N},
\end{equation}
where $C_{\ref{L:second-gaussian-estimate},N}=8\sum_{l=0}^N \binom{N}{l} (2\pi)^{l-N} C_{\ref{L:gaussian-bump-estimate},l} C_{\ref{L:faa-di-bruno},N-l}$.

For every $N\in{\mathbb N}$,
\begin{equation}
C_{\ref{L:second-gaussian-estimate},N}\le2^{20(N+1)^3}.
\end{equation}
Moreover,
\begin{equation}
C_{\ref{L:second-gaussian-estimate},0}<\tfrac{313}{512}2^{14}<2^{14},
\qquad
C_{\ref{L:second-gaussian-estimate},1}<\tfrac{43}{64}2^{19}<2^{19},
\end{equation}
\begin{equation}
C_{\ref{L:second-gaussian-estimate},2}<\tfrac{39}{64}2^{34}<2^{34},
\qquad
C_{\ref{L:second-gaussian-estimate},3}<\tfrac{49}{128}2^{56}<2^{56}.
\end{equation}

Let $\phi$ be a $W_0({\mathbb R})$ function such that
$\widehat{\phi}$ is supported in $[-1,1]$ and equal to $1$ on $[-1/2,1/2]$.
Let $\mu_\pm,\lambda_\pm\in\mathbb R$ be positive and satisfy
\begin{equation}
2\mu_-\le 2\lambda_-\le \lambda_+\le \mu_+,
\end{equation}
and let $\nu\in [-1,0)$.

Define a function $\rho$ by
\begin{equation}
\rho = \mathcal F^{-1}\left(\xi \mapsto (\widehat{\phi}(\lambda_-\xi) - \widehat{\phi}(\lambda_+\xi)) (\mathfrak{g}(\mu_- \xi)-\mathfrak{g}(\mu_+\xi))^{\nu}\right).
\end{equation}
Also, for $\xi \in {\mathbb R}$ we define
\begin{equation}
\varrho_0(\xi)=(\mathfrak{g}(\mu_{-}|\nu|^{1/2}\xi))^{-1}\widehat{\phi}(\lambda_{-}\xi)
\end{equation}
\begin{equation}
\varrho_1(\xi)=-(\mathfrak{g}(\mu_{-}|\nu|^{1/2}\xi))^{-1}\widehat{\phi}(\lambda_{+}\xi)
\end{equation}
\begin{equation}
\varrho_2(\xi)=(\mathfrak{g}(\mu_{-}|\nu|^{1/2}\xi))^{-1}\left(\widehat{\phi}(\lambda_{-}\xi)-\widehat{\phi}(\lambda_{+}\xi)\right)\left((1-\mathfrak{g}(t\xi))^{\nu} -1\right)
\end{equation}
with $t=\sqrt{\mu_{+}^2-\mu_{-}^2}$.
Then $\rho$ is a well-defined continuous function and
\begin{equation}
\rho=\sum_{l\in [3)} \mathcal F^{-1} (\varrho_l).
\end{equation}

For every $N\in{\mathbb N}$,
\begin{equation}
C_{\ref{four scale Gaussian kernel},N}\le2^{25(N+1)^3}.
\end{equation}
Moreover,
\begin{equation}
C_{\ref{four scale Gaussian kernel},2}<\tfrac{313}{512}2^{36},
\qquad
C_{\ref{four scale Gaussian kernel},3}<\tfrac{99}{128}2^{58}.
\end{equation}

For every $N\in{\mathbb N}$,
\begin{equation}
C_{\ref{mean four scale Gaussian kernel},N}\le2^{30(N+1)^3}.
\end{equation}
Moreover,
\begin{equation}
C_{\ref{mean four scale Gaussian kernel},2}<\tfrac{313}{512}2^{41}.
\end{equation}

For $1\le k\le n$, let $\mathcal{X}_k$ be the set of
double sequences
\begin{equation}
X=(X_{i,j})_{i\in [k),j\in {\mathbb Z}}
\end{equation}
with $X_{i,j}\in W_0({\mathbb R}^2)$.

Let $k\in{\mathbb N}$ with $1\le k\le n$. Let ${\rm M}(k)$ be the space of sequences $\mathbf{M}=(M_j)_{j\in {\mathbb Z}}$ such that for $j\in {\mathbb Z}$ we have
$M_j\in W_0(({\mathbb R}^2)^k)$. Define
\begin{equation}
\|\mathbf{M}\|_{{\rm M}(k)}:=\sup_{J\in{\mathbb N},\,J\ge1,\,\mathbf{F}\in\mathfrak F}\min(1,J^{-1+2^{k-n+1}}) |\Lambda_k(\sum_{j\in [J)} M_j)(\mathbf{F})| \, .
\end{equation}

For $q\in{\mathbb R}^2$ with $q_0,q_1>0$, $u\in[2)$, and $v\in\mathbb R^2$, define
\begin{equation} G_{q,u}(v) = \mathfrak{g}_{(q_0)}((W_u v)_0) \mathfrak{g}_{(q_1)}((W_u v)_1). \end{equation}
For $\gamma=(k,u,a)\in \Gamma$, define
\begin{equation} (G_{\gamma})_{i,j} = G_{a_i(j),u(i)}. \end{equation}

Let $\gamma=(k,u,a)\in \Gamma$.
Then $Y_\gamma\in \mathcal{X}_k$ and
\begin{equation}
\|\sum_{i\in [k)} \mathbf{M}(\gamma,Y_\gamma,i)\|_{{\rm M}(k)}\le 2.
\end{equation}

Let $\gamma=(k,u,a)\in \Gamma$. Let $X\in \mathcal{X}_k$ and assume for each $i\in [k)$ and  $j\in {\mathbb Z}$ we have
$X_{i,j}(u,v)=f_{i,j}(u)f_{i,j}(v)$ for some real valued $f_{i,j}\in W_0({\mathbb R})$.
Then for each $i\in [k)$, $j\in{\mathbb Z}$, and for all $\mathbf{F}\in {\mathfrak{F}}$,
\begin{equation}
\Lambda_k(\mathbf{M}(\gamma,X,i)_j)(\mathbf{F})\ge 0.
\end{equation}

Let $a\in A$ and $j\in{\mathbb Z}$.
Define the function $s(a,j):{\mathbb R} \to {\mathbb R}$ by
\begin{equation}s(a,j) = \mathcal{F}^{-1}(\xi \mapsto \sqrt{\mathfrak{g}(a(j-1)\xi)-\mathfrak{g}(a(j) \xi)}).\end{equation}

Let $\gamma=(k,u,a)\in \Gamma$. Let $i\in [k)$ and
$j\in {\mathbb Z}$. Define  $(s_{\gamma})_{i,j}: {\mathbb R} \to {\mathbb R}$ by
\begin{equation}
(s_{\gamma})_{i,j}=s(b,j)
\end{equation}
with
\begin{equation}
b(j)=\sqrt{a_{i}^0(j)^2 + a_{i}^1(j)^2}
\end{equation}
if $u_i=0$, and by
\begin{equation}
(s_{\gamma})_{i,j}=s(\sqrt{2}a_{i}^1,j)
\end{equation}
if $u_i=1$.

Let $\gamma=(k,u,a)\in \Gamma$. Define
$H_{\gamma}=(H_\gamma)_{i\in [k),j\in {\mathbb Z}}$ by
\begin{equation}
(H_{\gamma})_{i,j}:=(s_{\gamma})_{i,j}\otimes (s_{\gamma})_{i,j}
-(Y_{\gamma})_{i,j}
\end{equation}
for every $i\in [k), j\in\mathbb{Z}$.

For $\gamma=(k,u,a)\in \Gamma$, $i\in [k)$, $j\in {\mathbb Z}$, and $\xi\in {\mathbb R}$,
\begin{equation}
\widehat{(H_{\gamma})_{i,j}}(\xi,-\xi)=0\, .
\end{equation}

For $\gamma=(k,u,a)\in \Gamma$, $i\in [k)$, $j\in {\mathbb Z}$, and $z\in {\mathbb R}$,
\begin{equation}
\int_{{\mathbb R}} (H_{\gamma})_{i,j}(z+p,p)\,dp=0.
\end{equation}

Let $\gamma=(k,u,a)\in \Gamma$, $i\in [k)$, $j\in {\mathbb Z}$. For $t>0$, we set
\begin{equation}
(L_{\gamma,t})_{i,j} =(H_{\gamma})_{i,j} \ast_{(1,1)} \Phi_{(t)}.
\end{equation}

Let $\gamma=(k,u,a)\in \Gamma$ and $t>0$. Then $L_{\gamma,t} \in \mathcal{X}_k$ and for $i\in [k)$, $j\in {\mathbb Z}$, we have
\begin{equation}
\lim_{t\to 0_+} (L_{\gamma,t})_{i,j} = (H_{\gamma})_{i,j} \quad\text{in}\;L^1.
\end{equation}

Let $\gamma=(k,u,a)\in \Gamma$, $i\in [k)$, $j\in {\mathbb Z}$, $t>0$. Then
\begin{equation}
\lim_{t\to \infty} (L_{\gamma,t})_{i,j} = 0 \quad\text{in}\;L^1.
\end{equation}

Let $\gamma=(k,u,a)\in \Gamma$.

Define the index set
\begin{equation}\mathcal{I}_{\gamma} = \{(m,0)\,:\,m\in\mathbb{Z}, m\not=0\} \cup \{(0,l)\,:\,|l|\le \Delta_{\gamma}\} \subset \mathbb{Z}^2.\end{equation}

For every $\iota \in\mathcal{I}_{\gamma}$, we define  $L_{\gamma,\iota}=(L_{\gamma,\iota})_{i\in [k),j\in {\mathbb Z}}$
such that for $|l|\le \Delta_{\gamma}$,
\begin{equation}
(L_{\gamma,(0,l)})_{i,j}:= (H_{\gamma})_{i,j} \ast_{(1,1)} (\Phi_{(a_i^1(j+l-1))}-\Phi_{(a_i^1(j+l))})\, ,
\end{equation}

if $h>0$, then
\begin{equation}
(L_{\gamma,(h,0)})_{i,j}:= (H_{\gamma})_{i,j} \ast_{(1,1)} (\Phi_{(2^{h-1}a_i^1(j+\Delta_{\gamma}))}-\Phi_{(2^{h}a_i^1(j+\Delta_{\gamma}))})\, ,
\end{equation}
and if $h<0$, then
\begin{equation}
(L_{\gamma,(h,0)})_{i,j}:= (H_{\gamma})_{i,j} \ast_{(1,1)} (\Phi_{(2^{h}a_i^1(j-\Delta_{\gamma}-1))}-\Phi_{(2^{h+1}a_i^1(j-\Delta_{\gamma}-1))})\, .
\end{equation}

Let $X$ be a normed ${\mathbb R}$-vector space.
Let $\gamma=(k,u,a)\in \Gamma$ and let $D_\iota \in X$ for $\iota \in \mathcal{I}_{\gamma}$. We define
\begin{equation}
\sum_{\iota \in \mathcal{I}_{\gamma}} D_{\iota}:=\lim_{N\to \infty} \sum_{\iota \in\mathcal{I}_{\gamma}, ~|\iota| \leq N} D_{\iota},
\end{equation}
where the limit is taken in $X$.

Let $\gamma=(k,u,a)\in \Gamma$.
If $M=\sum_{\iota\in \mathcal{I}_\gamma} M_\iota$ holds in $L^1$ for $M,M_\iota\in W_0(({\mathbb R}^2)^k)$, then for every $\mathbf{F}\in\mathfrak{F}$,
\begin{equation} |\Lambda_k(M)(\mathbf{F})| \le \sum_{\iota\in \mathcal{I}_\gamma} |\Lambda_k(M_\iota)(\mathbf{F})|. \end{equation}

Let $\gamma=(k,u,a)\in \Gamma$ and assume $k\le n-1$.
Let $\nu=1$ if $k<n-1$ and $\nu=2$ if $k=n-1$ and let $i\in [k)$, $j\in {\mathbb Z}$.
For $\iota\in\mathcal{I}_{\gamma}$ define functions $\sigma_{\gamma,\iota,i,j}:{\mathbb R}\to{\mathbb R}$ so that
if $|l|\le \Delta_{\gamma}$,
\begin{equation} \sigma_{\gamma,(0,l),i,j} = s(a_i^1(\cdot+l), j) \end{equation}
and for $h>0$,
\begin{equation} \sigma_{\gamma,(h,0),i,j} = s(2^h a_i^1(\cdot+\Delta_{\gamma}), j) \end{equation}
and for $h<0$,
\begin{equation} \sigma_{\gamma,(h,0),i,j} = s(2^h a_i^1(\cdot-\Delta_{\gamma}), j). \end{equation}
For every $\iota\in\mathcal{I}_{\gamma}$ we define $N_{\gamma,\iota}= (N_{\gamma,\iota})_{i\in [k),j\in {\mathbb Z}}$ such that
\begin{equation}
(N_{\gamma,\iota})_{i,j} =
\mathcal F^{-1}((\xi,\eta) \mapsto \widehat{\sigma_{\gamma,\iota,i,j}}(\xi+\eta)^{-\nu}\widehat{(L_{\gamma,\iota})_{i,j}}(\xi,\eta))\, .
\end{equation}

Let $\gamma=(k,u,a)\in \Gamma$ and let $i\in [k)$.
There exists a finite multiset $\mathcal{P}\subset B_{\mathrm{dist}}(a_i^1,\Delta_\gamma)^2\times [2)$ with $\#\mathcal{P}= 6$ and for every $v\in {\mathbb R}^2$ and $j\in{\mathbb Z}$,
\begin{equation}|(H_\gamma)_{i,j}|(v) \le C_{\ref{H kernel estimate Gaussian domination}} \sum_{(t_0,t_1,u)\in\mathcal{P}} \langle (W_u v)_0\rangle_{(t_0(j))}^2 \langle (W_u v)_1\rangle_{(t_1(j))}^2, \end{equation}
where
$C_{\ref{H kernel estimate Gaussian domination}}
=
4C_{\ref{diagonal square root},2}^{\,2}
+
C_{\ref{Gaussian bump decay},0,2}^{\,2}.$

